begin;
create function pg_temp.progress_assert(ok boolean,label text)returns void language plpgsql as $$begin if ok is not true then raise exception 'FAIL: %',label;end if;end$$;
with u as(insert into auth.users(id,email)values(gen_random_uuid(),'progress-test@example.invalid')returning id)select set_config('folio.progress_owner',id::text,true)from u;
with u as(insert into auth.users(id,email)values(gen_random_uuid(),'progress-other@example.invalid')returning id)select set_config('folio.progress_other',id::text,true)from u;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('folio.progress_owner'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.progress_owner'),'is_anonymous',false)::text,true);
select public.initialize_workspace();
with l as(insert into public.loans(name,principal_paise,apr,tenure_months)values('Synthetic progress loan',120000,12,12)returning id)select set_config('folio.progress_loan',id::text,true)from l;
update public.loans set progress_first_due_on=folio_private.today()-60,payments_reported_through=folio_private.today()where id=current_setting('folio.progress_loan')::uuid;
select pg_temp.progress_assert((select progress_first_due_on=folio_private.today()-60 and payments_reported_through=folio_private.today() and principal_paise=120000 and tenure_months=12 and apr=12 from public.loans),'save owned progress metadata without changing financial terms');
select pg_temp.progress_assert((select count(*)=0 from public.transactions)and(select count(*)=0 from public.loan_payments),'reporting on-time payments never posts ledger records');
select pg_temp.progress_assert((public.workspace_snapshot()->'loans'->0->>'payments_reported_through')=folio_private.today()::text,'snapshot exposes saved report date to owner');
do $$begin begin update public.loans set payments_reported_through=folio_private.today()+1 where id=current_setting('folio.progress_loan')::uuid;exception when others then return;end;raise exception 'Future payment report accepted';end$$;
select set_config('request.jwt.claim.sub',current_setting('folio.progress_other'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.progress_other'),'is_anonymous',false)::text,true);
update public.loans set progress_first_due_on=folio_private.today()where id=current_setting('folio.progress_loan')::uuid;
select pg_temp.progress_assert((select count(*)=0 from public.loans),'other owner cannot read or update progress');
select set_config('request.jwt.claim.sub',current_setting('folio.progress_owner'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.progress_owner'),'is_anonymous',false)::text,true);
select pg_temp.progress_assert((select progress_first_due_on=folio_private.today()-60 from public.loans),'cross-owner update did not change metadata');
select 'PASS: owned loan progress, snapshot, future-date guard, unchanged terms/ledger and cross-owner isolation';
rollback;
